<template>
  <div>
    <el-button
      type="primary"
      plain
      icon="el-icon-plus"
      size="mini"
      @click="addAudio"
      >新增音频</el-button
    >
    <el-table
      :data="audioList"
      style="width: 100%"
      class="mt-10"
      v-loading="loading"
    >
      <el-table-column type="index" label="序号" align="center" />
      <el-table-column prop="name" label="音频名称" align="center" />
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <el-button
            type="text"
            @click="playAudio(scope.row)"
            class="el-icon-headset"
          ></el-button>
          <el-button
            type="text"
            @click="editData(scope.row)"
            class="el-icon-edit"
          ></el-button>
          <el-button
            type="text"
            @click="delData(scope.row)"
            class="el-icon-delete"
            style="color: red"
          ></el-button>
        </template>
      </el-table-column>
    </el-table>
    <pagination
      class="float-right mb-10"
      v-show="total > 0"
      :total="total"
      :page.sync="queryForm.page"
      :limit.sync="queryForm.size"
      @pagination="getData"
      layout="total, prev, pager, next"
      small
    />
    <el-dialog
      :title="title"
      :visible.sync="addVisible"
      width="50%"
      :close-on-click-modal="false"
    >
      <el-form
        :model="addForm"
        ref="addForm"
        label-width="120px"
        class="mt-20"
        size="small"
      >
        <el-form-item label="音频名称:" prop="name">
          <el-input v-model="addForm.name" style="width: 40%" />
        </el-form-item>
        <el-form-item label="音频文件:">
          <Upload
            :file="fileList"
            ref="Upload"
            :fileType="fileType"
            @setFileName="setFileName"
          />
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="addVisible = false">取 消</el-button>
        <el-button type="primary" @click="submitForm('addForm')"
          >确 定</el-button
        >
      </span>
    </el-dialog>
  </div>
</template>

<script>
import Upload from "@/components/upload.vue";
import { isFile } from "@/assets/utils/config";

export default {
  components: {
    Upload,
  },
  data() {
    return {
      audioList: [],
      loading: false,
      fileList: [],
      addForm: {},
      addVisible: false,
      title: "",
      UploadLoading: false,
      fileType: ["wav"],
      audio: null,
      queryForm: {
        page: 1,
        size: 10,
      },
      total: 0,
    };
  },
  created() {
    this.getData();
  },
  methods: {
    playAudio(row) {
      if (this.audio) {
        this.audio.pause();
      }
      this.audio = new Audio(`${row.audio_file}`);
      this.audio.play().catch((error) => {
        console.error("播放音频时发生错误:", error);
      });
    },
    setFileName(name) {
      if (!this.addForm.name) {
        const newName = name ? name.split(".").slice(0, -1).join(".") : name;
        this.$set(this.addForm, "name", newName);
      }
    },
    getData() {
      this.$api
        .get("/audio/getSysAudioList", {
          params: this.queryForm,
        })
        .then((res) => {
          if (res.data.data) {
            this.audioList = res.data.data;
            this.total = res.data.total;
          } else {
            this.audioList = [];
            this.total = 0;
          }
        });
    },
    addAudio() {
      this.addForm = {};
      this.fileList = [];
      this.title = "新增音频";
      this.addVisible = true;
    },
    editData(row) {
      this.title = "编辑音频";
      this.addVisible = true;
      this.addForm = { ...row };
      this.fileList = this.addForm.audio_file.split().map((item) => {
        return {
          name: item,
        };
      });
    },
    delData(row) {
      this.$confirm("是否删除该数据?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          this.$api.post("/audio/delSysAudio", { id: row.id }).then(() => {
            this.$message.success("操作成功");
            this.getData();
          });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    submitForm() {
      let formData = new FormData();
      this.addForm.audio_file = this.$refs.Upload.fileList[0];
      if (isFile(this.addForm.audio_file)) {
        formData.append("audio_file", this.addForm.audio_file);
      }
      formData.append("name", this.addForm.name);
      const isEditMode = !!this.addForm.id;
      const apiUrl = isEditMode
        ? "/audio/updateSysAudio"
        : "/audio/addSysAudio";
      if (isEditMode) {
        formData.append("id", this.addForm.id);
      }
      this.$api
        .post(apiUrl, formData, {
          headers: {
            "Content-Type": "multipart/form-data",
          },
          timeout: 600000,
        })
        .then(() => {
          this.UploadLoading = false;
          this.addVisible = false;
          this.$message.success("操作成功");
          this.getData();
        });
    },
  },
};
</script>

